import{_ as a,l as o,o as r,b as n,q as p,m as s,j as l,d as c}from"./chunks/framework.Tf23FRXt.js";const x=JSON.parse('{"title":"仙人彩","description":"","frontmatter":{},"headers":[{"level":2,"title":"仙人微彩","slug":"仙人微彩","link":"#仙人微彩","children":[]},{"level":2,"title":"仙人仙彩","slug":"仙人仙彩","link":"#仙人仙彩","children":[]}],"relativePath":"topic/gs-cactpot.htm.md","filePath":"topic/gs-cactpot.md","lastUpdated":1791101830000}'),i={name:"topic/gs-cactpot.htm.md"};function d(_,t,h,m,f,g){const e=o("SegmentText");return r(),n("div",null,[t[1]||(t[1]=p('<h1 id="仙人彩" tabindex="-1">仙人彩</h1><p>仙人彩其实就是小彩票活动，分为每天参加的仙人微彩，和每周开奖的仙人仙彩。</p><h2 id="仙人微彩" tabindex="-1">仙人微彩</h2><p>每天 23 点刷新，可以在综合柜台的仙人微彩发放员购买仙人微彩（刮刮乐）。基本玩法是刮开彩票上的 3 个数字（加上一开始给你的，一共是 4 个数），然后选择一条直线，根据这条直线上的 3 个数字的和决定获得的金碟币数量。每次购买需要 10 金碟币，每天可以购买 3 次。</p><p>通常推荐使用微彩计算器：<a href="https://ff14-cactpot.wotax.net/" target="_blank" rel="noreferrer">Cactpot Solver</a>，另外也有大佬用 Python 写的<a href="https://bbs.nga.cn/read.php?tid=14587834" target="_blank" rel="noreferrer">本地版计算器</a> (可以了解计算器原理顺便看看源码……</p><h2 id="仙人仙彩" tabindex="-1">仙人仙彩</h2><p>在演出广场 2 楼，甚至有专门的传送点。每周六 21 点现场开奖 (有开奖表演，推荐去围观)。这是数字型彩票，100 金碟币向仙人仙彩发放员购买彩票，每张彩票上可以依次选择 4 个数字，每周可以购买 3 张。每次开奖后 1 小时 (周六晚 9~10 点) 有前期兑换奖励 (有额外的金碟币加成)，在本周六开奖后，到下周六开奖前，都是兑奖期，无论是否中奖都记得去兑奖哦。</p>',7)),s(e,{className:"blue"},{default:l(()=>[...t[0]||(t[0]=[c("p",null,"奖券数字将以个位开始依次向左 (高位) 计算，比如大奖数字是 1234，那么如果你购买的彩票是 1230，则视为没有猜中（五等奖阳光普照），如果你购买的是 7654，那么视为猜中 1 个数字，可以获得四等奖。若购买的是 2334，则是猜中 2 个数字（三等奖），以此类推。",-1)])]),_:1})])}const b=a(i,[["render",d]]);export{x as __pageData,b as default};
